import React, { useState, useEffect, useMemo } from "react";
import { Link, useNavigate } from "react-router-dom";
import "./css/HealthAssessment.css";
import logoImage from "../assets/aqi.webp";

function HealthAssessment() {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [formData, setFormData] = useState({
    age_group: "",
    gender: "",
    respiratory_conditions: [],
    smoking_history: "",
    living_environment: [],
    common_symptoms: [],
    occupational_exposure: "",
    medical_history: [],
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [saveStatus, setSaveStatus] = useState("");
  const [username, setUsername] = useState("");
  const [isMobileView, setIsMobileView] = useState(window.innerWidth <= 768);
  const [showResult, setShowResult] = useState(false);

  const navigate = useNavigate();

  const API_BASE_URL =
    process.env.NODE_ENV === "production"
      ? "https://airaware-app-gcw7.onrender.com"
      : "http://localhost:8000";

  // ✅ Get logged-in user from localStorage
  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    setUsername(user.username || "User");
  }, []);

  // ✅ Handle responsive view
  useEffect(() => {
    const handleResize = () => setIsMobileView(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // ✅ All questions
  const questions = [
    {
      id: "age_group",
      title: "What is your age group?",
      subtitle: "Age affects air quality sensitivity",
      type: "radio",
      options: [
        "0-12 years",
        "13-18 years",
        "19-40 years",
        "41-60 years",
        "61 years and above",
      ],
    },
    {
      id: "gender",
      title: "What is your gender?",
      subtitle: "Gender can influence health risk factors",
      type: "radio",
      options: ["Male", "Female", "Other", "Prefer not to say"],
    },
    {
      id: "respiratory_conditions",
      title: "Do you have any respiratory conditions?",
      subtitle: "Respiratory health affects air quality sensitivity",
      type: "checkbox",
      options: ["Asthma", "COPD", "Chronic Bronchitis", "Emphysema", "None"],
    },
    {
      id: "smoking_history",
      title: "Smoking History",
      subtitle: "Smoking significantly impacts respiratory health",
      type: "radio",
      options: [
        "Never smoked",
        "Former smoker",
        "Current smoker",
        "Exposed to secondhand smoke",
      ],
    },
    {
      id: "living_environment",
      title: "Living Environment",
      subtitle: "Your environment affects daily air quality exposure",
      type: "checkbox",
      options: ["Urban area", "Industrial zone", "Rural area", "Coastal area"],
    },
    {
      id: "common_symptoms",
      title: "Common Symptoms",
      subtitle: "Current symptoms that may be air quality related",
      type: "checkbox",
      options: [
        "Frequent coughing",
        "Shortness of breath",
        "Wheezing",
        "Chest tightness",
        "None",
      ],
    },
    {
      id: "occupational_exposure",
      title: "Occupational Exposure",
      subtitle: "Work environment affects exposure to pollutants",
      type: "radio",
      options: [
        "Construction/Mining",
        "Chemical Industry",
        "Healthcare",
        "Agriculture",
        "Office Environment",
        "Other",
      ],
    },
    {
      id: "medical_history",
      title: "Medical History",
      subtitle: "Existing conditions that may increase air quality sensitivity",
      type: "checkbox",
      options: [
        "Hypertension",
        "Diabetes",
        "Heart Disease",
        "Allergies",
        "Immunocompromised",
        "None of the above",
      ],
    },
  ];

  // ✅ Handle option selection
  const handleOptionChange = (questionId, value, isCheckbox = false) => {
    setFormData((prev) => {
      if (isCheckbox) {
        const currentValues = prev[questionId] || [];
        if (value === "None" || value === "None of the above") {
          return { ...prev, [questionId]: [value] };
        } else {
          const filtered = currentValues.filter(
            (v) => v !== "None" && v !== "None of the above"
          );
          return {
            ...prev,
            [questionId]: filtered.includes(value)
              ? filtered.filter((v) => v !== value)
              : [...filtered, value],
          };
        }
      } else {
        return { ...prev, [questionId]: value };
      }
    });
  };

  // ✅ Validation per question
  const isQuestionAnswered = (index) => {
    const q = questions[index];
    const value = formData[q.id];
    if (q.type === "checkbox") return Array.isArray(value) && value.length > 0;
    return !!value;
  };

  const nextQuestion = () => {
    if (isQuestionAnswered(currentQuestion)) {
      setCurrentQuestion((prev) => prev + 1);
      setError("");
    } else {
      setError("Please select an option before proceeding.");
      setTimeout(() => setError(""), 2500);
    }
  };

  const prevQuestion = () => {
    if (currentQuestion > 0) setCurrentQuestion((prev) => prev - 1);
  };

  // ✅ Submit Health Assessment
  const handleSubmit = async () => {
    if (!isQuestionAnswered(currentQuestion)) {
      setError("Please answer all questions before submitting.");
      return;
    }

    const storedUser = JSON.parse(localStorage.getItem("user"));
    if (!storedUser || !storedUser.user_id) {
      setError("Could not identify user. Please log in again.");
      return navigate("/login");
    }

    setLoading(true);
    setSaveStatus("Saving...");

    const payload = {
      ...formData,
      user_id: storedUser.user_id, // ✅ FIXED
    };

    try {
      const response = await fetch(`${API_BASE_URL}/api/health-assessment/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });

      const data = await response.json();

      if (response.ok && data.success) {
        console.log("✅ Health assessment saved:", data);
        setSaveStatus("✅ Health assessment saved successfully!");
        setShowResult(true);
        setTimeout(() => navigate("/dashboard"), 3000);
      } else {
        console.error("❌ Save failed:", data.error);
        setError(data.error || "Failed to save health assessment.");
        setSaveStatus("❌ Save failed");
      }
    } catch (err) {
      console.error("❌ Network error:", err);
      setError("Network error. Please try again.");
      setSaveStatus("❌ Network error");
    } finally {
      setLoading(false);
    }
  };

  // ✅ Result Screen
  if (showResult) {
    return (
      <div className="result-screen">
        <h1>Assessment Complete!</h1>
        <p>Thank you, {username}! Your assessment has been saved.</p>
        <p>Redirecting to dashboard...</p>
      </div>
    );
  }

  // ✅ Render current question
  const q = questions[currentQuestion];
  const progress = ((currentQuestion + 1) / questions.length) * 100;

  return (
    <div className="health-assessment-page">
      <nav className="navbar">
        <Link to="/" className="navbar-brand">
          <img src={logoImage} alt="AirAware" width="40" height="40" />
          AirAware
        </Link>
      </nav>

      <div className="container">
        <h2>{q.title}</h2>
        <p>{q.subtitle}</p>

        {error && <div className="error">{error}</div>}

        <div className="options">
          {q.options.map((option) => (
            <div
              key={option}
              className={`option ${
                q.type === "checkbox"
                  ? formData[q.id]?.includes(option)
                    ? "selected"
                    : ""
                  : formData[q.id] === option
                  ? "selected"
                  : ""
              }`}
              onClick={() =>
                handleOptionChange(q.id, option, q.type === "checkbox")
              }
            >
              {option}
            </div>
          ))}
        </div>

        <div className="actions">
          {currentQuestion > 0 && (
            <button onClick={prevQuestion}>← Previous</button>
          )}
          {currentQuestion < questions.length - 1 ? (
            <button onClick={nextQuestion}>Next →</button>
          ) : (
            <button onClick={handleSubmit} disabled={loading}>
              {loading ? "Submitting..." : "Submit"}
            </button>
          )}
        </div>

        <div className="progress">
          <div className="progress-bar" style={{ width: `${progress}%` }}></div>
        </div>

        {saveStatus && <p className="status-text">{saveStatus}</p>}
      </div>
    </div>
  );
}

export default HealthAssessment;
